import math

def tau(n):
    """Calculates the number of divisors of n."""
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def is_exotic_tau(tau_n):
    """Checks if tau_n is twice an odd integer."""
    if tau_n <= 0:
        return False
    # tau_n = 2 * k, where k is odd.
    # This means tau_n must be even, and tau_n / 2 must be odd.
    if tau_n % 2 != 0:
        return False
    k = tau_n // 2
    return k % 2 != 0

def find_nth_exotic_tau(N):
    """Finds the Nth integer n such that tau(n) is twice an odd integer."""
    count = 0
    n = 1
    found_numbers = []

    # Set a practical limit for the search, although the theoretical limit is unknown.
    # Since primes are included, we expect it not to be excessively large.
    MAX_N_SEARCH = 30000 

    while count < N and n <= MAX_N_SEARCH:
        t = tau(n)
        if is_exotic_tau(t):
            count += 1
            found_numbers.append(n)
        n += 1

    if count < N:
        return None, f"Search limit {MAX_N_SEARCH} reached before finding the {N}th element."
    return found_numbers[-1], None

# We need the 132nd exotic integer.
N_target = 132
result, error = find_nth_exotic_tau(N_target)

if error:
    print(f"Error: {error}")
else:
    print(f"The {N_target}th integer n is: {result}")

